userms::Vector2f operator*(const Userms::Vector2f& other) {
    float x = (float) this->x / (float) other.x;
    float y = (float) this->y / (float) other.y;
    return Userms::Vector2f(x, y);
}

userface::Userface::Userface* Userface::GetUserface(int index)
{
    if (index < 0 || index >= m_userfaces.size())
        return nullptr;

    return &m_userfaces[index];
}
